/// <summary>
/// CB220_PlannerCodes Update buyer group on matching item coverage records service
/// </summary>
class METReqItemTableBuyerGroupUpdService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// processing logic
    /// </summary>
    /// <param name = "_dataContract">The data contract</param>
    public void process(METReqItemTableBuyerGroupUpdContract _dataContract)
    {
        #OCCRetryCount
        ReqItemTable                reqItemTable;
        METReqItemTable             METReqItemTable;
        InventDim                   inventDim;
        METVendSiteSettingsSetup    vendSiteSettingsSetup;
        QueryRun                    queryRun = new QueryRun(_dataContract.getQuery());
        boolean                     error = false;
        //VendAccount                 vendAccount = _dataContract.parmVendAccount();
        //ItemBuyerGroupId            itemBuyerGroupId = _dataContract.parmItemBuyerGroupId();
         
        while (queryRun.next())
        {
            vendSiteSettingsSetup = queryRun.get(tableNum(METVendSiteSettingsSetup));
            
            setPrefix(strFmt("@MET:METReqItemTableBuyerGroupUpdServicePrefix", tableId2PName(tableNum(METVendSiteSettingsSetup)),
                                                                               vendSiteSettingsSetup.AssignedVendorAccount,
                                                                               vendSiteSettingsSetup.AssignedSite,
                                                                               vendSiteSettingsSetup.AssignedWH,
                                                                               vendSiteSettingsSetup.ItemBuyerGroupId));

            try
            {
                // For each matching record taken from Vendor site settings form, find matching records in ‘Item coverage’ form
                // using Vendor account/ Site/Warehouse values combination taken from Vendor site settings form.
                // Update Buyer group on the matching record(s)
                ttsbegin;

                update_recordset METReqItemTable
                setting ItemBuyerGroupId = vendSiteSettingsSetup.ItemBuyerGroupId
                join reqItemTable
                    where reqItemTable.RecId == METReqItemTable.RefRecId
                       && reqItemTable.ItemCovFieldsActive == NoYes::Yes
                       && reqItemTable.VendId == vendSiteSettingsSetup.AssignedVendorAccount
                join inventDim
                    where inventDim.inventDimId == reqItemTable.CovInventDimId
                       && inventDim.InventSiteId == vendSiteSettingsSetup.AssignedSite
                       && inventDim.InventLocationId == vendSiteSettingsSetup.AssignedWH;

                ttscommit;
                info("@SYS93392");
            }
            catch (Exception::Deadlock)
            {
                retry;
            }
            catch (Exception::UpdateConflict)
            {
                if (appl.ttsLevel() == 0)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        throw Exception::UpdateConflictNotRecovered;
                    }
                    else
                    {
                        retry;
                    }
                }
                else
                {
                    throw Exception::UpdateConflict;
                }
            }
            catch (Exception::Error)
            {
                error("@MET:ItemCoverageUpdateError");
                error = true;
            }

        }

        if (error)
        {
            // throw error so the batch status is updated to error.
            throw error("@MET:CompletedWithErrors");
        }
        else
        {
            info("@SYS9265");
        }
    }
